package com.example.takura.content.controller;
import com.example.takura.content.application.ContentService;import com.example.takura.content.application.ContentService.Draft;import com.example.takura.identity.controller.StaffRequestPrincipal;import com.example.takura.identity.domain.StaffPrincipal;import java.net.URI;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") public class ContentController {private final ContentService service;ContentController(ContentService s){service=s;}
 @GetMapping("/services")List<?> services(@RequestParam(required=false)UUID cursor,@RequestParam(defaultValue="12")int page_size){return service.list("SERVICE",null,cursor,page_size);}
 @GetMapping("/services/{slug}")ResponseEntity<?> service(@PathVariable String slug){return detail("SERVICE",slug);}
 @GetMapping("/projects")List<?> projects(@RequestParam(required=false)String category,@RequestParam(required=false)UUID cursor,@RequestParam(defaultValue="12")int page_size){return service.list("PROJECT",category,cursor,page_size);}
 @GetMapping("/projects/{slug}")ResponseEntity<?> project(@PathVariable String slug){return detail("PROJECT",slug);}
 @GetMapping(value="/sitemap.xml",produces=MediaType.APPLICATION_XML_VALUE)String sitemap(){StringBuilder xml=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?><urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">");for(String type:List.of("SERVICE","PROJECT"))for(var item:service.list(type,null,null,100))xml.append("<url><loc>https://example.invalid/").append(type.toLowerCase()).append("s/").append(item.slug()).append("</loc></url>");return xml.append("</urlset>").toString();}
 private ResponseEntity<?> detail(String type,String slug){try{return ResponseEntity.ok().cacheControl(CacheControl.maxAge(java.time.Duration.ofSeconds(60)).cachePublic()).body(service.get(type,slug));}catch(ContentService.RedirectException r){return ResponseEntity.status(308).location(URI.create("/"+type.toLowerCase()+"s/"+r.slug)).build();}}
 @PutMapping("/admin/content/{id}")ResponseEntity<Void> revise(@StaffRequestPrincipal StaffPrincipal actor,@PathVariable UUID id,@RequestHeader(value="If-Match",required=false)String match,@RequestParam(defaultValue="false")boolean publish,@RequestBody Draft draft){if(match==null)return ResponseEntity.status(428).build();service.revise(actor,id,Long.parseLong(match.replace("\"","")),draft,publish);return ResponseEntity.noContent().eTag('"'+Long.toString(Long.parseLong(match.replace("\"",""))+1)+'"').build();}
}
